    TEST_ASSERT_EQUAL_STRING("2 0 calc(98% - 87px)", mb("calc(98% - 87px)", 20000, 16000));
    TEST_ASSERT_EQUAL_STRING("2 0 calc(91% + 264px)", mb("calc(239px + calc(91% + 25px))", 20000, 16000));
    TEST_ASSERT_EQUAL_STRING("2 0 calc(24% - 8px)", mb("calc(24% - 8px)", 16000, 16000));
    TEST_ASSERT_EQUAL_STRING("2 0 max(3%, 23px, clamp(calc(80% - 15px), 95%, calc(76% - 66px)), calc(75% - 33px))", mb("max(3%, 23px, clamp(calc(80% - 15px), 95%, calc(76% - 66px)), calc(75% - 33px))", 20000, 16000));
    TEST_ASSERT_EQUAL_STRING("2 0 calc(67% - 182px)", mb("calc(67% - 182px)", 16000, 16000));
